(function(){
  'use strict';
  // Known nonce field name -> WP action. Bare `_wpnonce` fields are NOT
  // refreshed without a data-wpins-nonce-action marker: minting a nonce for
  // the wrong action breaks the form, while the cached nonce stays valid
  // for the cache lifetime (the plugin extends nonce_life to the cache TTL).
  var KNOWN_NONCE_ACTIONS = {
    'woocommerce-process-checkout-nonce': 'woocommerce-process_checkout',
    'woocommerce-add-to-cart-nonce': 'woocommerce-add-to-cart'
  };
  function resolveAction(el) {
    var attr = el.getAttribute('data-wpins-nonce-action');
    if (attr) { return attr; }
    if (el.name && KNOWN_NONCE_ACTIONS[el.name]) { return KNOWN_NONCE_ACTIONS[el.name]; }
    return null;
  }
  function initHydrator() {
    var config = window._wpinsHydrateConfig || {};
    var endpoint = config.endpoint || '/wp-json/wp-instant/v1/nonces';

    // Collect nonce inputs on page
    var nonceInputs = document.querySelectorAll('input[name="_wpnonce"], input[name="woocommerce-process-checkout-nonce"], input[name="woocommerce-add-to-cart-nonce"], [data-wpins-nonce-action]');
    if (!nonceInputs.length && !document.querySelector('.cart-contents, .cart-count, .mini-cart-count')) {
      return;
    }

    var refreshable = [];
    var actions = ['wp_rest'];
    nonceInputs.forEach(function(el) {
      var act = resolveAction(el);
      if (act) {
        refreshable.push({ el: el, action: act });
        if (actions.indexOf(act) === -1) {
          actions.push(act);
        }
      }
    });

    fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ actions: actions })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (!data || !data.success || !data.nonces) return;

      // Update nonce inputs (only those with a known action)
      refreshable.forEach(function(item) {
        if (data.nonces[item.action]) {
          item.el.value = data.nonces[item.action];
        }
      });

      // Update WooCommerce Cart Badge if returned (Woo-specific selectors only)
      if (typeof data.cart_count !== 'undefined') {
        var cartBadges = document.querySelectorAll('.cart-contents-count, .cart-count, .mini-cart-count');
        cartBadges.forEach(function(badge) {
          badge.textContent = data.cart_count;
        });
      }
    })
    .catch(function() {});
  }

  if (window.requestIdleCallback) {
    requestIdleCallback(initHydrator);
  } else {
    setTimeout(initHydrator, 100);
  }
})();
